// Package lucide is the complete Lucide icon set (lucide-static, ISC; see
// LICENSE), the default icons of shadcn/ui: 24-unit grid, 2-unit round
// strokes.
//
//	ui.Icon(c, lucide.ChevronDown)
//
// Former Lucide names are kept as aliases (Filter is Funnel, AlertCircle is
// CircleAlert, …).
//
// Every icon is a statically initialized variable, so a program links only
// the icons it references. Register makes the whole set reachable by name
// ("lucide:" plus the Lucide name, e.g. icon.ByName("lucide:search"),
// aliases included).
//
// The icons are generated by internal/cmd/icongen; do not edit icons.go.
//
// Experimental: this package's API may change in any 0.x release (see
// docs/release.md, "API 稳定性"); icon names follow the upstream set and
// may change when it is updated.
package lucide

import "github.com/tangoui/tango/ui/icon"

// Register registers every icon of the set, and its former names, with
// icon.ByName under "lucide:" names. It links the whole set into the
// program.
func Register() {
	icon.Register(All()...)
	for name, ic := range aliases() {
		icon.RegisterAs(name, ic)
	}
}
